-- AarogyaVaani hospital schema. Run in Supabase SQL editor or `supabase db push`.
create extension if not exists pgcrypto;
create type public.app_role as enum ('patient','doctor','admin');
create type public.appointment_status as enum ('scheduled','checked_in','waiting','in_consultation','completed','cancelled');
create table public.profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, full_name text, phone text, email text, role public.app_role not null default 'patient', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.patients (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, patient_id text not null unique default ('PT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), abha_id text unique, full_name text not null, date_of_birth date, gender text, phone text, email text, address text, emergency_contact text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.doctors (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, doctor_id text not null unique, full_name text not null, department text, specialization text, license_number text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.family_members (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete cascade, name text not null, relationship text not null, date_of_birth date, gender text, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.appointments (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id), doctor_id uuid not null references public.doctors(id), appointment_date date not null, appointment_time time, reason text, token_number integer, status public.appointment_status not null default 'scheduled', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index appointments_daily_token on public.appointments(doctor_id,appointment_date,token_number) where token_number is not null;
create table public.consultations (id uuid primary key default gen_random_uuid(), appointment_id uuid not null unique references public.appointments(id), patient_id uuid not null references public.patients(id), doctor_id uuid not null references public.doctors(id), symptoms text, diagnosis text, doctor_notes text, status text not null default 'completed', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.symptom_entries (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete cascade, appointment_id uuid references public.appointments(id), symptom_text text not null, input_method text not null check (input_method in ('typed','voice')), language text, recorded_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.medicines (id uuid primary key default gen_random_uuid(), name text not null, strength text, dosage_form text, generic_name text, created_at timestamptz not null default now());
create table public.prescriptions (id uuid primary key default gen_random_uuid(), consultation_id uuid not null references public.consultations(id), patient_id uuid not null references public.patients(id), doctor_id uuid not null references public.doctors(id), medicine_name text not null, quantity text, dosage text, morning boolean default false, afternoon boolean default false, evening boolean default false, night boolean default false, duration text, instructions text, created_at timestamptz not null default now());
create table public.medical_documents (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete cascade, family_member_id uuid references public.family_members(id) on delete cascade, document_type text not null, title text not null, document_date date, doctor_name text, hospital_name text, description text, storage_path text not null unique, source text not null default 'patient_uploaded' check(source in ('patient_uploaded','hospital_generated')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete cascade, family_member_id uuid references public.family_members(id) on delete cascade, report_type text not null, title text not null, report_date date, hospital_name text, description text, storage_path text not null unique, source text not null default 'patient_uploaded', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.queue (id uuid primary key default gen_random_uuid(), appointment_id uuid not null unique references public.appointments(id), patient_id uuid not null references public.patients(id), doctor_id uuid not null references public.doctors(id), token_number integer not null, status public.appointment_status not null default 'waiting', check_in_time timestamptz, called_time timestamptz, completed_time timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.is_doctor() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from doctors where user_id=auth.uid())$$;
create or replace function public.owns_patient(pid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from patients where id=pid and user_id=auth.uid())$$;
create or replace function public.doctor_assigned(pid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from appointments a join doctors d on d.id=a.doctor_id where a.patient_id=pid and d.user_id=auth.uid())$$;
create or replace function public.doctor_login_email(p_doctor_id text) returns text language sql security definer set search_path=public as $$select u.email from public.doctors d join auth.users u on u.id=d.user_id where d.doctor_id=p_doctor_id$$;
grant execute on function public.doctor_login_email(text) to anon, authenticated;
alter table public.profiles enable row level security; alter table public.patients enable row level security; alter table public.doctors enable row level security; alter table public.family_members enable row level security; alter table public.appointments enable row level security; alter table public.consultations enable row level security; alter table public.symptom_entries enable row level security; alter table public.prescriptions enable row level security; alter table public.medicines enable row level security; alter table public.medical_documents enable row level security; alter table public.reports enable row level security; alter table public.queue enable row level security;
create policy "self profile" on public.profiles for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own patient" on public.patients for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "assigned doctor reads patient" on public.patients for select using(public.doctor_assigned(id));
create policy "doctor self" on public.doctors for select using(user_id=auth.uid()); create policy "own family" on public.family_members for all using(public.owns_patient(patient_id)) with check(public.owns_patient(patient_id));
create policy "patient appointments" on public.appointments for select using(public.owns_patient(patient_id)); create policy "doctor appointments" on public.appointments for all using(doctor_id in(select id from public.doctors where user_id=auth.uid())) with check(doctor_id in(select id from public.doctors where user_id=auth.uid()));
create policy "patient symptoms" on public.symptom_entries for all using(public.owns_patient(patient_id)) with check(public.owns_patient(patient_id)); create policy "doctor symptoms" on public.symptom_entries for select using(public.doctor_assigned(patient_id));
create policy "patient consultations" on public.consultations for select using(public.owns_patient(patient_id)); create policy "doctor consultations" on public.consultations for all using(public.doctor_assigned(patient_id) and doctor_id in(select id from doctors where user_id=auth.uid())) with check(public.doctor_assigned(patient_id) and doctor_id in(select id from doctors where user_id=auth.uid()));
create policy "patient prescriptions" on public.prescriptions for select using(public.owns_patient(patient_id)); create policy "doctor prescriptions" on public.prescriptions for all using(public.doctor_assigned(patient_id) and doctor_id in(select id from doctors where user_id=auth.uid())) with check(public.doctor_assigned(patient_id) and doctor_id in(select id from doctors where user_id=auth.uid()));
create policy "own documents" on public.medical_documents for all using(public.owns_patient(patient_id)) with check(public.owns_patient(patient_id)); create policy "doctor documents" on public.medical_documents for select using(public.doctor_assigned(patient_id)); create policy "own reports" on public.reports for all using(public.owns_patient(patient_id)) with check(public.owns_patient(patient_id)); create policy "doctor reports" on public.reports for select using(public.doctor_assigned(patient_id));
create policy "own queue" on public.queue for select using(public.owns_patient(patient_id)); create policy "doctor queue" on public.queue for all using(doctor_id in(select id from doctors where user_id=auth.uid())) with check(doctor_id in(select id from doctors where user_id=auth.uid()));
-- Private bucket: create it in Dashboard, then use these storage policies.
insert into storage.buckets(id,name,public) values ('medical-files','medical-files',false) on conflict(id) do nothing;
create policy "patients manage own files" on storage.objects for all to authenticated using(bucket_id='medical-files' and (storage.foldername(name))[1]='patients' and public.owns_patient(((storage.foldername(name))[2])::uuid)) with check(bucket_id='medical-files' and (storage.foldername(name))[1]='patients' and public.owns_patient(((storage.foldername(name))[2])::uuid));
create policy "assigned doctor reads files" on storage.objects for select to authenticated using(bucket_id='medical-files' and (storage.foldername(name))[1]='patients' and public.doctor_assigned(((storage.foldername(name))[2])::uuid));
